cat > /root/autodl-tmp/setup_openvla_part2.sh << 'SCRIPT'
#!/bin/bash
set -e
PIP=/root/autodl-tmp/conda_envs/openvla/bin/pip
PYTHON=/root/autodl-tmp/conda_envs/openvla/bin/python

echo "=== Part2 Step 1: Install openvla package ==="
cd /root/autodl-tmp/openvla
$PIP install -e . 2>&1 | tail -5

echo "=== Part2 Step 2: Install LIBERO from PyPI ==="
$PIP install libero 2>&1 | tail -5

echo "=== Part2 Step 3: Install LIBERO eval requirements ==="
$PIP install -r /root/autodl-tmp/openvla/experiments/robot/libero/libero_requirements.txt 2>&1 | tail -5

echo "=== Part2 Step 4: Try flash-attn ==="
$PIP install flash-attn --no-build-isolation 2>&1 | tail -10 || echo "flash-attn failed, will use eager attention"

echo "=== Part2 Step 5: Version check ==="
$PYTHON -c "
import transformers; print('transformers:', transformers.__version__)
import torch; print('torch:', torch.__version__, 'cuda:', torch.cuda.is_available())
try:
    import libero; print('libero: OK')
except: print('libero: FAIL')
try:
    import flash_attn; print('flash_attn:', flash_attn.__version__)
except: print('flash_attn: not installed')
"

echo "=== Part2 DONE ==="
SCRIPT
chmod +x /root/autodl-tmp/setup_openvla_part2.sh
echo "part2 script created"
